DateTime scheduledDate = Get<DateTime>("ScheduledDate");
DateTime today = DateTime.Today;


int daysUntilDue = (scheduledDate - today).Days;

if(daysUntilDue >= 0 && daysUntilDue <= 7 ){
	Set<String>("ReminderType","Upcoming");
}else if(daysUntilDue < 0 ){
	Set<String>("ReminderType","Overdue");
}else{
	Set<String>("ReminderType","None");
}


return true;
